module k_multihedgehog_checker(\n    input wire [3:0] n,\n    input wire [3:0] k,\n    input wire [15:0] adj [0:15],\n    output reg valid\n);\n\n    function [3:0] count_bits;\n        input [15:0] x;\n        integer j;\n        begin\n            count_bits = 4'd0;\n            for (j = 0; j < 16; j = j + 1)\n                count_bits = count_bits + x[j];\n        end\n    endfunction\n\n    reg [3:0] deg [0:15];\n    reg [15:0] visited;\n    reg [3:0] layer [0:15];\n    reg [3:0] parent [0:15];\n    reg [3:0] queue [0:15];\n    reg [3:0] head, tail;\n    reg [3:0] candidate, i, v, u;\n    reg all_visited;\n    reg [3:0] max_layer;\n    reg valid_candidate;\n    integer iter;\n\n    always @(*) begin\n        valid = 1'b0;\n        if (k > 4'd3) begin\n            valid = 1'b0;\n        end else begin\n            for (i = 4'd0; i < 4'd16; i = i + 4'd1) begin\n                deg[i] = (i < n) ? count_bits(adj[i]) : 4'd0;\n            end\n            \n            for (candidate = 4'd0; candidate < n; candidate = candidate + 4'd1) begin\n                if (!valid && deg[candidate] >= 4'd3) begin\n                    visited = 16'd0;\n                    for (i = 4'd0; i < 4'd16; i = i + 4'd1) begin\n                        layer[i] = 4'd0;\n                        parent[i] = 4'd16;\n                    end\n                    head = 4'd0;\n                    tail = 4'd0;\n                    queue[tail] = candidate;\n                    tail = tail + 4'd1;\n                    visited[candidate] = 1'b1;\n                    layer[candidate] = 4'd0;\n                    parent[candidate] = 4'd16;\n                    \n                    for (iter = 0; iter < 16; iter = iter + 1) begin\n                        if (head < tail) begin\n                            u = queue[head];\n                            head = head + 4'd1;\n                            for (v = 4'd0; v < 4'd16; v = v + 4'd1) begin\n                                if (v < n && adj[u][v] && !visited[v]) begin\n                                    visited[v] = 1'b1;\n                                    layer[v] = layer[u] + 4'd1;\n                                    parent[v] = u;\n                                    queue[tail] = v;\n                                    tail = tail + 4'd1;\n                                end\n                            end\n                        end\n                    end\n                    \n                    all_visited = 1'b1;\n                    for (i = 4'd0; i < n; i = i + 4'd1) begin\n                        if (!visited[i]) all_visited = 1'b0;\n                    end\n                    \n                    max_layer = 4'd0;\n                    for (i = 4'd0; i < n; i = i + 4'd1) begin\n                        if (layer[i] > max_layer) max_layer = layer[i];\n                    end\n                    \n                    if (all_visited && max_layer == k) begin\n                        valid_candidate = 1'b1;\n                        for (i = 4'd0; i < n; i = i + 4'd1) begin\n                            if (layer[i] == 4'd0 && deg[i] < 4'd3) valid_candidate = 1'b0;\n                            else if (layer[i] > 4'd0 && layer[i] < k && deg[i] < 4'd4) valid_candidate = 1'b0;\n                            else if (layer[i] == k && deg[i] != 4'd1) valid_candidate = 1'b0;\n                        \n                        end\n                        if (valid_candidate) valid = 1'b1;\n                    end\n                end\n            end\n        end\n    end\nendmodule